     1	package com.loja.strategy.coupon;
     2	
     3	import com.loja.dto.CheckoutRequest;
     4	import com.loja.dto.ItemRequest;
     5	import com.loja.domain.Product;
     6	import com.loja.service.MoneyRounding;
     7	import org.springframework.stereotype.Component;
     8	import java.math.BigDecimal;
     9	import java.util.List;
    10	import java.util.Map;
    11	
    12	@Component
    13	public class Buy3Pay2Coupon implements CouponStrategy {
    14	    @Override
    15	    public String getCode() {
    16	        return "BUY3PAY2";
    17	    }
    18	
    19	    @Override
    20	    public BigDecimal calculateDiscount(CheckoutRequest request, Map<String, Product> products, BigDecimal productsSubtotal, BigDecimal shippingCost) {
    21	        BigDecimal discount = BigDecimal.ZERO;
    22	
    23	        for (ItemRequest item : request.getItems()) {
    24	            if (item.getQuantity() >= 3) {
    25	                Product product = products.get(item.getSku());
    26	                int freeItems = item.getQuantity() / 3;
    27	                discount = discount.add(product.getPrice().multiply(new BigDecimal(freeItems)));
    28	            }
    29	        }
    30	
    31	        return MoneyRounding.round(discount);
    32	    }
    33	
    34	    @Override
    35	    public boolean isApplicable(CheckoutRequest request, List<String> customerOrderStatuses) {
    36	        return true;
    37	    }
    38	}
