content.content:
  1	package com.loja.service;
  2	
  3	import com.loja.domain.Order;
  4	import com.loja.domain.Product;
  5	import com.loja.dto.CheckoutRequest;
  6	import com.loja.dto.SummaryResponse;
  7	import com.loja.exception.OrderException;
  8	import com.loja.repository.OrderRepository;
  9	import com.loja.repository.ProductRepository;
 10	import com.loja.strategy.club.ClubBenefits;
 11	import com.loja.strategy.club.ClubTierStrategy;
 12	import com.loja.strategy.coupon.CouponStrategy;
 13	import com.loja.strategy.payment.PaymentResult;
 14	import com.loja.strategy.payment.PaymentStrategy;
 15	import com.loja.strategy.shipping.ShippingResult;
 16	import com.loja.strategy.shipping.ShippingStrategy;
 17	import org.springframework.http.HttpStatus;
 18	import org.springframework.stereotype.Service;
 19	import org.springframework.transaction.annotation.Transactional;
 20	
 21	import java.math.BigDecimal;
 22	import java.util.HashMap;
 23	import java.util.List;
 24	import java.util.Map;
 25	import java.util.stream.Collectors;
 26	
 27	@Service
 28	public class CheckoutService {
 29	    private final ProductRepository productRepository;
 30	    private final OrderRepository orderRepository;
 31	    private final Map<String, CouponStrategy> coupons;
 32	    private final Map<String, ShippingStrategy> shippingMethods;
 33	    private final Map<String, PaymentStrategy> paymentMethods;
 34	    private final Map<String, ClubTierStrategy> clubTiers;
 35	
 36	    public CheckoutService(
 37	            ProductRepository productRepository,
 38	            OrderRepository orderRepository,
 39	            List<CouponStrategy> couponList,
 40	            List<ShippingStrategy> shippingList,
 41	            List<PaymentStrategy> paymentList,
 42	            List<ClubTierStrategy> clubList) {
 43	        this.productRepository = productRepository;
 44	        this.orderRepository = orderRepository;
 45	        this.coupons = couponList.stream().collect(Collectors.toMap(CouponStrategy::getCode, c -> c));
 46	        this.shippingMethods = shippingList.stream().collect(Collectors.toMap(ShippingStrategy::getCode, s -> s));
 47	        this.paymentMethods = paymentList.stream().collect(Collectors.toMap(PaymentStrategy::getCode, p -> p));
 48	        this.clubTiers = clubList.stream().collect(Collectors.toMap(ClubTierStrategy::getCode, t -> t));
 49	    }
 50	
 51	    @Transactional(readOnly = true)
 52	    public SummaryResponse calculateSummary(CheckoutRequest request) {
 53	        validateRequest(request);
 54	
 55	        Map<String, Product> productMap = loadProducts(request);
 56	
 57	        BigDecimal productsSubtotal = calculateProductsSubtotal(request, productMap);
 58	        BigDecimal totalWeightKg = calculateTotalWeight(request, productMap);
 59	
 60	        ShippingResult shippingResult = calculateShipping(request, totalWeightKg);
 61	
 62	        ClubTierStrategy clubTier = getClubTier(request.getClubTier());
 63	        ClubBenefits clubBenefits = clubTier.getBenefits(request, productsSubtotal);
 64	
 65	        BigDecimal shippingCost = clubBenefits.isFreeShipping() ? BigDecimal.ZERO : shippingResult.getCost();
 66	        int deliveryDays = shippingResult.getDeliveryDays();
 67	
 68	        BigDecimal couponDiscount = calculateCouponDiscount(request, productMap, productsSubtotal, shippingCost);
 69	
 70	        BigDecimal insurance = calculateInsurance(request, productsSubtotal);
 71	
 72	        BigDecimal orderTotal = productsSubtotal
 73	            .subtract(couponDiscount)
 74	            .add(shippingCost)
 75	            .add(insurance);
 76	
 77	        PaymentResult paymentResult = calculatePayment(request, orderTotal);
 78	
 79	        BigDecimal credit = MoneyRounding.round(
 80	            productsSubtotal.multiply(clubBenefits.getCreditPercentage())
 81	        );
 82	
 83	        boolean gift = clubBenefits.getGiftThreshold() != null &&
 84	                      productsSubtotal.compareTo(clubBenefits.getGiftThreshold()) > 0;
 85	
 86	        SummaryResponse summary = new SummaryResponse();
 87	        summary.setProductsSubtotal(productsSubtotal);
 88	        summary.setCouponDiscount(couponDiscount);
 89	        summary.setShippingCost(shippingCost);
 90	        summary.setDeliveryDays(deliveryDays);
 91	        summary.setInsurance(insurance);
 92	        summary.setPaymentAdjustment(paymentResult.getAdjustment());
 93	        summary.setFinalTotal(paymentResult.getFinalTotal());
 94	        summary.setInstallments(paymentResult.getInstallments());
 95	        summary.setInstallmentAmount(paymentResult.getInstallmentAmount());
 96	        summary.setNextPurchaseCredit(credit);
 97	        summary.setGift(gift);
 98	
 99	        return summary;
100	    }
101	
102	    private void validateRequest(CheckoutRequest request) {
103	        if (request.getCustomer() == null || request.getCustomer().getCpf() == null ||
104	            request.getCustomer().getEmail() == null) {
105	            throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
106	        }
107	
108	        if (request.getItems() == null || request.getItems().isEmpty()) {
109	            throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
110	        }
111	
112	        Map<String, Long> skuCount = request.getItems().stream()
113	            .collect(Collectors.groupingBy(item -> item.getSku(), Collectors.counting()));
114	
115	        for (var item : request.getItems()) {
116	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
117	                throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
118	            }
119	            if (skuCount.get(item.getSku()) > 1) {
120	                throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
121	            }
122	        }
123	    }
124	
125	    private Map<String, Product> loadProducts(CheckoutRequest request) {
126	        List<String> skus = request.getItems().stream()
127	            .map(item -> item.getSku())
128	            .collect(Collectors.toList());
129	
130	        List<Product> products = productRepository.findAllById(skus);
131	
132	        if (products.size() != skus.size()) {
133	            throw new OrderException("UNKNOWN_PRODUCT", HttpStatus.UNPROCESSABLE_ENTITY);
134	        }
135	
136	        Map<String, Product> productMap = new HashMap<>();
137	        for (Product product : products) {
138	            productMap.put(product.getSku(), product);
139	
140	            if (product.getDiscontinued()) {
141	                throw new OrderException("PRODUCT_DISCONTINUED", HttpStatus.UNPROCESSABLE_ENTITY);
142	            }
143	
144	            int requestedQty = request.getItems().stream()
145	                .filter(item -> item.getSku().equals(product.getSku()))
146	                .findFirst()
147	                .get()
148	                .getQuantity();
149	
150	            if (product.getStock() < requestedQty) {
151	                throw new OrderException("INSUFFICIENT_STOCK", HttpStatus.UNPROCESSABLE_ENTITY);
152	            }
153	        }
154	
155	        return productMap;
156	    }
157	
158	    private BigDecimal calculateProductsSubtotal(CheckoutRequest request, Map<String, Product> products) {
159	        BigDecimal subtotal = BigDecimal.ZERO;
160	        for (var item : request.getItems()) {
161	            Product product = products.get(item.getSku());
162	            subtotal = subtotal.add(product.getPrice().multiply(new BigDecimal(item.getQuantity())));
163	        }
